class OutputPathBusyError(RuntimeError):
    pass


def _normalized_writer_output_identity(path: str | Path) -> tuple[str, str]:
    raw_path = str(path).strip()
    if not raw_path:
        raise ValueError("Memory export output MOD path is missing")
    candidate = Path(raw_path).expanduser()
    try:
        resolved = candidate.resolve(strict=False)
    except (OSError, RuntimeError):
        resolved = Path(os.path.abspath(os.fspath(candidate)))
    display_path = os.path.normpath(str(resolved))
    return os.path.normcase(display_path), display_path


def _try_acquire_writer_named_mutex(output_key: str) -> tuple[dict[str, Any] | None, str]:
    """Serialize the physical NewMOD writer across Launcher processes."""
    if os.name != "nt":
        return {"handle": 0, "name": "", "abandoned": False}, ""
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.CreateMutexW.argtypes = [ctypes.c_void_p, wintypes.BOOL, wintypes.LPCWSTR]
    kernel32.CreateMutexW.restype = wintypes.HANDLE
    kernel32.WaitForSingleObject.argtypes = [wintypes.HANDLE, wintypes.DWORD]
    kernel32.WaitForSingleObject.restype = wintypes.DWORD
    kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel32.CloseHandle.restype = wintypes.BOOL
    digest = hashlib.sha256(str(output_key).encode("utf-8", errors="surrogatepass")).hexdigest().upper()
    name = f"Local\\PC_REHD_Code_X_Writer_Output_{digest}"
    handle = kernel32.CreateMutexW(None, False, name)
    if not handle:
        raise OSError(ctypes.get_last_error(), f"CreateMutexW failed for {name}")
    wait_result = int(kernel32.WaitForSingleObject(handle, 0))
    if wait_result in {0x00000000, 0x00000080}:  # WAIT_OBJECT_0 / WAIT_ABANDONED
        return {
            "handle": handle,
            "name": name,
            "abandoned": wait_result == 0x00000080,
        }, ""
    kernel32.CloseHandle(handle)
    if wait_result == 0x00000102:  # WAIT_TIMEOUT
        return None, name
    raise OSError(ctypes.get_last_error(), f"WaitForSingleObject failed for {name}: {wait_result}")


def _release_writer_named_mutex(lease: dict[str, Any] | None) -> None:
    if not lease or os.name != "nt" or not lease.get("handle"):
        return
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.ReleaseMutex.argtypes = [wintypes.HANDLE]
    kernel32.ReleaseMutex.restype = wintypes.BOOL
    kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel32.CloseHandle.restype = wintypes.BOOL
    handle = lease["handle"]
    try:
        if not kernel32.ReleaseMutex(handle):
            raise OSError(ctypes.get_last_error(), f"ReleaseMutex failed for {lease.get('name', '')}")
    finally:
        kernel32.CloseHandle(handle)


# Keep the mutex registry in a stable synthetic module so SHA-versioned Writer
# reloads inside one Launcher process still share the same active writers.
_OUTPUT_MUTEX_STATE_MODULE = "_pc_rehd_code_x_output_mutex_v1"
_output_mutex_candidate = type(sys)(_OUTPUT_MUTEX_STATE_MODULE)
_output_mutex_candidate.guard = threading.Lock()
_output_mutex_candidate.entries = {}
_OUTPUT_MUTEX_STATE = sys.modules.setdefault(_OUTPUT_MUTEX_STATE_MODULE, _output_mutex_candidate)
_OUTPUT_MUTEX_GUARD: threading.Lock = _OUTPUT_MUTEX_STATE.guard
_OUTPUT_MUTEX_ENTRIES: dict[str, dict[str, Any]] = _OUTPUT_MUTEX_STATE.entries

# Deferred advisory work yields whenever a real export is active. This keeps a
# previous UV report from stealing the reusable Writer process during the next
# MOD write while avoiding any dependency between report success and export.
_DEFERRED_ADVISORY_CONDITION = threading.Condition(threading.Lock())
_DEFERRED_ADVISORY_MAIN_OPERATIONS = 0


def _enter_writer_main_operation() -> None:
    global _DEFERRED_ADVISORY_MAIN_OPERATIONS
    with _DEFERRED_ADVISORY_CONDITION:
        _DEFERRED_ADVISORY_MAIN_OPERATIONS += 1


def _leave_writer_main_operation() -> None:
    global _DEFERRED_ADVISORY_MAIN_OPERATIONS
    with _DEFERRED_ADVISORY_CONDITION:
        _DEFERRED_ADVISORY_MAIN_OPERATIONS = max(
            0,
            _DEFERRED_ADVISORY_MAIN_OPERATIONS - 1,
        )
        if _DEFERRED_ADVISORY_MAIN_OPERATIONS == 0:
            _DEFERRED_ADVISORY_CONDITION.notify_all()


def _wait_for_writer_main_operation() -> None:
    with _DEFERRED_ADVISORY_CONDITION:
        while _DEFERRED_ADVISORY_MAIN_OPERATIONS > 0:
            _DEFERRED_ADVISORY_CONDITION.wait(timeout=0.25)


def _try_acquire_output_path_mutex(
    output_mod: str | Path,
    *,
    max_process_id: int,
    request_id: str,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    output_key, display_path = _normalized_writer_output_identity(output_mod)
    thread_id = threading.get_ident()
    with _OUTPUT_MUTEX_GUARD:
        entry = _OUTPUT_MUTEX_ENTRIES.get(output_key)
        if entry is None:
            named_mutex, _named_mutex_name = _try_acquire_writer_named_mutex(output_key)
            if named_mutex is None:
                return None, {
                    "python_process_id": 0,
                    "thread_id": 0,
                    "max_process_id": 0,
                    "request_id": "<cross-process>",
                    "output_mod": display_path,
                    "output_key": output_key,
                    "started_at": 0.0,
                    "cross_process": True,
                }
            path_lock = threading.RLock()
            if not path_lock.acquire(blocking=False):
                _release_writer_named_mutex(named_mutex)
                raise RuntimeError("New output-path RLock could not be acquired")
            owner = {
                "token": f"{os.getpid()}:{thread_id}:{time.monotonic_ns()}",
                "python_process_id": os.getpid(),
                "thread_id": thread_id,
                "max_process_id": int(max_process_id),
                "request_id": str(request_id).strip(),
                "output_mod": display_path,
                "output_key": output_key,
                "started_at": time.time(),
                "depth": 1,
                "named_mutex": named_mutex,
            }
            _OUTPUT_MUTEX_ENTRIES[output_key] = {"lock": path_lock, "owner": owner}
            return {"output_key": output_key, "token": owner["token"]}, None

        path_lock = entry["lock"]
        if not path_lock.acquire(blocking=False):
            return None, dict(entry["owner"])
        owner = entry["owner"]
        if int(owner.get("thread_id", -1)) != thread_id:
            path_lock.release()
            return None, dict(owner)
        owner["depth"] = int(owner.get("depth", 1)) + 1
        if not str(owner.get("request_id", "") or "").strip() and str(request_id).strip():
            owner["request_id"] = str(request_id).strip()
        return {"output_key": output_key, "token": owner["token"]}, None


def _acquire_output_path_mutex(
    output_mod: str | Path,
    *,
    max_process_id: int,
    request_id: str,
) -> dict[str, Any]:
    lease, conflict = _try_acquire_output_path_mutex(
        output_mod,
        max_process_id=max_process_id,
        request_id=request_id,
    )
    if lease is not None:
        return lease
    owner = conflict or {}
    owner_request = str(owner.get("request_id", "") or "").strip() or "<pending>"
    current_request = str(request_id).strip() or "<pending>"
    raise OutputPathBusyError(
        "同一 NEW MOD 正在由另一个导出任务写入，已拒绝本次任务。 / "
        "The same NEW MOD is already owned by another writer; this task was rejected.\n"
        f"Owner Python PID: {owner.get('python_process_id', 0)}\n"
        f"Owner Max PID: {owner.get('max_process_id', 0)}\n"
        f"Owner Request ID: {owner_request}\n"
        f"Current Max PID: {int(max_process_id)}\n"
        f"Current Request ID: {current_request}\n"
        f"Output: {owner.get('output_mod', output_mod)}"
    )


def _release_output_path_mutex(lease: dict[str, Any]) -> None:
    output_key = str(lease.get("output_key", "") or "")
    token = str(lease.get("token", "") or "")
    with _OUTPUT_MUTEX_GUARD:
        entry = _OUTPUT_MUTEX_ENTRIES.get(output_key)
        if entry is None:
            raise RuntimeError("Output-path mutex lease is no longer registered")
        owner = entry["owner"]
        if str(owner.get("token", "")) != token:
            raise RuntimeError("A stale output-path mutex lease attempted to release another writer")
        depth = int(owner.get("depth", 1)) - 1
        owner["depth"] = depth
        entry["lock"].release()
        if depth <= 0:
            _OUTPUT_MUTEX_ENTRIES.pop(output_key, None)
            _release_writer_named_mutex(owner.get("named_mutex"))

