STANDARD_RE6_EXPORT_MESH_NAME_RE = re.compile(r"(?i)^Mesh_(\d{3,})(?=$|[^0-9])")
MESH_NAME_FVF_RE = re.compile(r"(?i)^Mesh_\d{3,}_X?([0-9A-F]{8})(?=_|$)")
COMPACT_BLENDER_RE6_MESH_NAME_RE = re.compile(
    r"(?i)^(?P<mesh_slot>0*[1-9]\d*)_X(?P<header_fvf>[0-9A-F]{8})_"
    r"(?P<lod_level>-?\d+)_(?P<material_id>-?\d+)_(?P<group_id>-?\d+)_"
    r"(?P<display_mode>-?\d+)_(?P<mesh_type>-?\d+)"
    r"(?:_Import(?:[2-9]|[1-9]\d+)(?:_[1-9]\d*)?)?$"
)
# Older Launcher builds appended a long Header token to an otherwise valid
# Blender compact name.  Keep this read-only compatibility grammar until the
# user edits the name again, then the rename path below writes the canonical
# compact form back to the scene.
LEGACY_COMPACT_BLENDER_RE6_MESH_NAME_RE = re.compile(
    r"(?i)^(?P<mesh_slot>0*[1-9]\d*)_X(?P<header_fvf>[0-9A-F]{8})_"
    r"(?P<lod_level>-?\d+)_(?P<material_id>-?\d+)_(?P<group_id>-?\d+)_"
    r"(?P<display_mode>-?\d+)_(?P<mesh_type>-?\d+)"
    r"(?P<legacy_suffix>(?:_(?:Import(?:[2-9]|[1-9]\d+)(?:_[1-9]\d*)?|"
    r"LODx-?\d+|MatID:-?\d+|Group:-?\d+|DisplayMode:-?\d+|Type:-?\d+))*)$"
)
LEGACY_COMPACT_BLENDER_RE6_MESH_SUFFIX_TOKEN_RE = re.compile(
    r"(?i)_(?:"
    r"(?P<import_suffix>Import(?:[2-9]|[1-9]\d+)(?:_[1-9]\d*)?)|"
    r"LODx(?P<lod_level>-?\d+)|"
    r"MatID:(?P<material_id>-?\d+)|"
    r"Group:(?P<group_id>-?\d+)|"
    r"DisplayMode:(?P<display_mode>-?\d+)|"
    r"Type:(?P<mesh_type>-?\d+)"
    r")"
)
MOD_MESH_SLOT_MAX = 0xFFFF
MESH_SLOT_LIMIT_PLAN_CONTRACT = "pc-rehd-mesh-slot-limit-plan"
FVF_WEIGHT_CAPACITY_POLICY_SCHEMA = "pc-rehd-fvf-weight-capacity-v1"
FVF_WEIGHT_EPSILON = 0.000001


def _parse_compact_blender_re6_mesh_name(value: Any) -> dict[str, Any] | None:
    """Read the compact Blender name and the old appended-token variant."""
    text = str(value or "").strip()
    compact = COMPACT_BLENDER_RE6_MESH_NAME_RE.fullmatch(text)
    legacy_suffix = ""
    if compact is None:
        compact = LEGACY_COMPACT_BLENDER_RE6_MESH_NAME_RE.fullmatch(text)
        if compact is None:
            return None
        legacy_suffix = str(compact.group("legacy_suffix") or "")
    facts: dict[str, Any] = {
        "mesh_slot": int(compact.group("mesh_slot")),
        "mesh_slot_text": str(compact.group("mesh_slot")),
        "header_fvf": "0x" + str(compact.group("header_fvf")).upper(),
        "header_fvf_text": str(compact.group("header_fvf")).upper(),
        "lod_level": int(compact.group("lod_level")),
        "material_id": int(compact.group("material_id")),
        "group_id": int(compact.group("group_id")),
        "display_mode": int(compact.group("display_mode")),
        "mesh_type": int(compact.group("mesh_type")),
        "import_suffix": "",
        "legacy_compact_suffix": legacy_suffix,
    }
    if not legacy_suffix:
        match = re.search(
            r"(?i)(_Import(?:[2-9]|[1-9]\d+)(?:_[1-9]\d*)?)$", text
        )
        facts["import_suffix"] = str(match.group(1) if match is not None else "")
        return facts
    for token in LEGACY_COMPACT_BLENDER_RE6_MESH_SUFFIX_TOKEN_RE.finditer(legacy_suffix):
        import_suffix = token.group("import_suffix")
        if import_suffix is not None:
            facts["import_suffix"] = "_" + str(import_suffix)
            continue
        for field in (
            "lod_level",
            "material_id",
            "group_id",
            "display_mode",
            "mesh_type",
        ):
            raw_value = token.group(field)
            if raw_value is not None:
                facts[field] = int(raw_value)
    return facts


def _format_compact_blender_re6_mesh_name(facts: Mapping[str, Any]) -> str:
    return (
        f"{str(facts.get('mesh_slot_text') or int(facts['mesh_slot']))}_"
        f"X{str(facts.get('header_fvf_text') or str(facts['header_fvf'])[2:]).upper()}_"
        f"{int(facts['lod_level'])}_{int(facts['material_id'])}_"
        f"{int(facts['group_id'])}_{int(facts['display_mode'])}_"
        f"{int(facts['mesh_type'])}{str(facts.get('import_suffix') or '')}"
    )

