def _collect_oversized_mesh_auto_split_notice(contract: dict[str, Any]) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    seen_slots: set[int] = set()
    for mesh in contract.get("meshes", []):
        if not isinstance(mesh, dict):
            continue
        if not (_has_semantic_mesh_payload(mesh) or _has_binary_mesh_payload(mesh)):
            continue
        vertex_count = _int_or_default(mesh.get("vert_count"), 0)
        if vertex_count <= 0 and _has_semantic_mesh_payload(mesh):
            vertex_count = _get_semantic_vertex_count(mesh)
        if vertex_count <= MESH_HEADER_VERTEX_COUNT_MAX:
            continue
        mesh_slot = _int_or_default(mesh.get("mesh_slot"), 0)
        if mesh_slot in seen_slots:
            continue
        seen_slots.add(mesh_slot)
        records.append(
            {
                "mesh_slot": mesh_slot,
                "mesh_name": _format_uv_risk_mesh_name(mesh),
                "vertex_count": vertex_count,
                "minimum_piece_count": max(
                    2,
                    (vertex_count + MESH_HEADER_VERTEX_COUNT_MAX - 1) // MESH_HEADER_VERTEX_COUNT_MAX,
                ),
            }
        )
    return sorted(records, key=lambda record: (record["mesh_slot"], record["mesh_name"]))


def _show_native_oversized_mesh_auto_split_notice(records: list[dict[str, Any]]) -> None:
    chinese_ui = runtime_ui_is_chinese()
    lines = [
        (
            f"Mesh_{record['mesh_slot']:03d}: {record['vertex_count']:,} 个顶点"
            if chinese_ui
            else f"Mesh_{record['mesh_slot']:03d}: {record['vertex_count']:,} vertices"
        )
        for record in records[:12]
    ]
    title = "RE6 MOD - 自动拆分大型 MESH" if chinese_ui else "RE6 MOD - Automatic large Mesh split"
    message = (
        "检测到单个 MESH 超过 65,535 个顶点。Python 将按完整三角面自动拆成多个 .MOD MESH 槽，导出会继续。\n\n"
        "以后把 NewMOD 再导入 Max 时，您会看到更多 Mesh_* 对象，这是正常结果。\n\n"
        if chinese_ui
        else "A Mesh exceeds 65,535 vertices. Python will preserve complete triangles and automatically split it into multiple .MOD Mesh slots. Export will continue.\n\n"
        "When the NewMOD is imported into Max again, additional Mesh_* objects are expected.\n\n"
    ) + "\n".join(lines)
    try:
        import ctypes

        ctypes.windll.user32.MessageBoxW(None, message, title, 0x00000040 | 0x00010000 | 0x00040000)
    except Exception:
        try:
            sys.stderr.write(title + "\n" + message + "\n")
        except Exception:
            pass


