def _oversized_mesh_auto_split_notice_sidecar_path(job_file: str | Path) -> Path:
    job_path = Path(job_file)
    return job_path.with_name(job_path.stem + "_mesh_split_notice.json")


def _show_oversized_mesh_auto_split_notice_once(
    job_file: Path,
    records: list[dict[str, Any]],
    *,
    show_notice: Any | None = None,
) -> Path | None:
    if not records:
        return None
    sidecar = _oversized_mesh_auto_split_notice_sidecar_path(job_file)
    token_payload = [
        {
            "mesh_slot": _int_or_default(record.get("mesh_slot"), 0),
            "vertex_count": _int_or_default(record.get("vertex_count"), 0),
        }
        for record in records
    ]
    token = hashlib.sha256(
        json.dumps(token_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    try:
        existing = runtime_read_json_file(sidecar)
        if isinstance(existing, dict) and str(existing.get("token", "")) == token:
            return sidecar
    except Exception:
        pass
    notice_callback = show_notice if callable(show_notice) else _show_oversized_mesh_auto_split_notice
    notice_callback(records)
    try:
        _atomic_write_bytes(
            sidecar,
            json.dumps({"token": token, "records": token_payload}, ensure_ascii=False, indent=2).encode("utf-8"),
        )
    except OSError:
        # The notice is advisory and must never block an otherwise valid export.
        return None
    return sidecar


